export const rock = defineMove({
  keeps: "Move",
  name: "rock",
  tune: {
    size: [metres(0.22), metres(1.5)],
    throwSpeed: metresPerSecond(12),
    maxCharge: seconds(0.45),
    throwHeight: metres(1.1),
    range: metres(10),
    fromTheGround: {
      tearAhead: body.radius + metres(0.32),
      buried: metres(0.2),
      coilsPast: share(0.5),
    },
    fromTheRubble: { snapUp: metres(0.45) },
    throughTheWall: { startsAt: share(0.2), endsAt: share(1) },
    afterTheThrowWalk: share(0.4),
  },
  *run(kesar: Kesar, rock, world): Script { ... }
});

*run(kesar: Kesar, rock, world): Script {
  const wallsTheWay = world.walls.between(
    kesar.pos.up(rock.throwHeight),
    kesar.target,
  );
  const throwing = yield* Throwing({ charge: 0, from: Infinity });
  if (world.rocks.takeRubble())
    yield* fromTheRubble(kesar, rock, world, throwing);
  else if (wallsTheWay)
    yield* throughTheWall(kesar, rock, wallsTheWay, throwing);
  else yield* fromTheGround(kesar, rock, world, throwing);
  // A pressed once the throw started: another rock
  if (kesar.pressed("A", { since: throwing.from })) kesar.repeatWhenDone();
  // if you summon a wall in the middle, queue it up as an action
},

